	[ 'eans' => [ '4003322308966' ], 'html' => '<p>Hvidvinsglas fra Spiegelaus Definition-serie med løvtynde vægge og en vægt på blot 105 gram pr. glas. Den lave vægt gør dem lette at holde om.</p><ul><li>Rumfang 43 cl</li><li>105 gram pr. glas</li><li>6 stk. i sættet</li></ul>' ],
