	[ 'eans' => [ '8592973118490' ], 'html' => '<p>Hjemmelavede grissini skæres i ét hug med Tescomas rulleudstikker. Når dejen er rullet ud på pladen, fører du rullen henover, og strimlerne er klar til ovnen uden at skulle skæres enkeltvis.</p>' ],
